// `pnpm build:css`: compiles src/page/tailwind.css with the Tailwind CLI and
// writes the result into src/page/styles.generated.ts as a string the Worker
// inlines. The generated file is committed, so deploying needs no build.

import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';

export const CSS_INPUT = 'src/page/tailwind.css';
export const CSS_MODULE = 'src/page/styles.generated.ts';

// The module wrapping the compiled stylesheet.
export const cssModule = (css: string): string =>
    `// Generated by \`pnpm build:css\` from ${CSS_INPUT}; do not edit.\nexport const PAGE_CSS = ${JSON.stringify(css.trim())};\n`;

const compile = (): string => {
    const dir = mkdtempSync(join(tmpdir(), 'myip-probe-css-'));
    const output = join(dir, 'page.css');
    try {
        const run = spawnSync('pnpm', ['exec', 'tailwindcss', '--input', CSS_INPUT, '--output', output, '--minify'], { stdio: ['ignore', 'ignore', 'inherit'] });
        if (run.status !== 0) throw new Error('Tailwind build failed');
        return readFileSync(output, 'utf8');
    } finally {
        rmSync(dir, { recursive: true, force: true });
    }
};

if (import.meta.main) {
    writeFileSync(CSS_MODULE, cssModule(compile()));
    console.log(`Wrote ${CSS_MODULE}`);
}
